class SafetyHubScreen extends StatefulWidget { const SafetyHubScreen({super.key}); @override State<SafetyHubScreen> createState()=>_SafetyHubScreenState(); }
class _SafetyHubScreenState extends State<SafetyHubScreen>{
 late final SafetyRepository repo; bool loading=true,sending=false; String? error; List<TrustedContact> contacts=[];
 @override void initState(){super.initState();repo=SafetyRepository(ApiClient(SessionStore()));load();}
 Future<void> load()async{setState((){loading=true;error=null;});try{final x=await repo.contacts();if(mounted)setState(()=>contacts=x);}catch(e){if(mounted)setState(()=>error='Safety details could not be loaded. Pull down to retry.');}finally{if(mounted)setState(()=>loading=false);}}
 Future<Position?> location()async{try{var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)return null;return await Geolocator.getCurrentPosition();}catch(_){return null;}}
 Future<void> sos()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(icon:const Icon(Icons.sos_rounded,color:Colors.red,size:50),title:const Text('Activate emergency SOS?'),content:const Text('Your latest location and account details will be shared with uDrive safety operations.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(style:FilledButton.styleFrom(backgroundColor:Colors.red),onPressed:()=>Navigator.pop(c,true),child:const Text('Send SOS'))]));if(ok!=true)return;setState(()=>sending=true);try{final pos=await location();await repo.raiseSos(type:'SOS',description:'Immediate assistance requested from the mobile application.',latitude:pos?.latitude,longitude:pos?.longitude,accuracy:pos?.accuracy);if(mounted)showDialog<void>(context:context,barrierDismissible:false,builder:(c)=>AlertDialog(icon:const Icon(Icons.verified_user_rounded,color:Colors.green,size:50),title:const Text('SOS sent'),content:const Text('uDrive safety operations have received your emergency alert.'),actions:[FilledButton(onPressed:()=>Navigator.pop(c),child:const Text('Understood'))]));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('SOS could not be sent. Call local emergency services if you are in immediate danger.')));}finally{if(mounted)setState(()=>sending=false);}}
